import{_ as s,a0 as i,w as l,s as a,ao as d,I as e,x as r,a1 as n,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"我成為軟件工程師的原因和經歷 | LCTT x X-CMD","titleTemplate":false,"description":"我成為軟件工程師的原因和經歷 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我成為軟件工程師的原因和經歷 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我成為軟件工程師的原因和經歷 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20160429 Why and how I became a software engineer","title":"我成為軟件工程師的原因和經歷","tag":"201611","desc":""},"relativePath":"201611/20160429 Why and how I became a software engineer.md","filePath":"[post].md"}'),u={name:"201611/20160429 Why and how I became a software engineer.md"};function f(g,t,m,w,T,b){const o=i("Link");return l(),a("div",null,[t[32]||(t[32]=d('<h1 id="我成為軟件工程師的原因和經歷" tabindex="-1">我成為軟件工程師的原因和經歷 <a class="header-anchor" href="#我成為軟件工程師的原因和經歷" aria-label="Permalink to “我成為軟件工程師的原因和經歷”">​</a></h1><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/myopensourcestory.png?itok=6TXlAkFi" alt=""></p><p>1989 年烏干達首都，坎帕拉。</p><p>我明智的父母決定與其將我留在家裏添麻煩，不如把我送到叔叔的辦公室學學電腦。幾天後，我和另外六、七個小孩，還有一台放置在課桌上的嶄新電腦，一起置身於 21 層樓的一間狹小房屋中。很明顯我們還不夠格去碰那傢伙。在長達三週無趣的 DOS 命令學習後，美好時光來到，終於輪到我來輸 <strong>copy doc.txt d:</strong> 啦。</p><p>那將文件寫入五英寸軟盤的奇怪的聲音，聽起來卻像音樂般美妙。那段時間，這塊軟盤簡直成為了我的至寶。我把所有可以拷貝的東西都放在上面了。然而，1989 年的烏干達，人們的生活十分“正統”，相比較而言，搗鼓電腦、拷貝文件還有格式化磁盤就稱不上“正統”。於是我不得不專注於自己接受的教育，遠離計算機科學，走入建築工程學。</p><p>之後幾年裏，我和同齡人一樣，幹過很多份工作也學到了許多技能。我教過幼兒園的小朋友，也教過大人如何使用軟件，在服裝店工作過，還在教堂中擔任過引座員。在我獲取堪薩斯大學的學位時，我正在技術管理員的手下做技術助理，聽上去比較神氣，其實也就是搞搞學生資料庫而已。</p><p>當我 2007 年畢業時，計算機技術已經變得不可或缺。建築工程學的方方面面都與計算機科學深深的交織在一起，所以我們不經意間學了些簡單的編程知識。我對於這方面一直很着迷，但我不得不成為一位“正統”的工程師，由此我發展了一項秘密的私人愛好：寫科幻小説。</p><p>在我的故事中，我以我筆下的女主角的形式存在。她們都是編程能力出眾的科學家，總是捲入冒險，並用自己的技術發明戰勝那些渣渣們，有時甚至要在現場發明新方法。我提到的這些“新技術”，有的是基於真實世界中的發明，也有些是從科幻小説中讀到的。這就意味着我需要了解這些技術的原理，而且我的研究使我關注了許多有趣的 reddit 版塊和電子雜誌。</p><h3 id="開源-巨大的寶庫" tabindex="-1">開源：巨大的寶庫 <a class="header-anchor" href="#開源-巨大的寶庫" aria-label="Permalink to “開源：巨大的寶庫”">​</a></h3><p>那幾周在 DOS 命令上花費的經歷對我影響巨大，我在一些非專業的項目上耗費心血，並佔據了寶貴的學習時間。Geocities 剛向所有 Yahoo! 用户開放時，我就創建了一個網站，用於發佈一些用小型數碼相機拍攝的個人圖片。我建立多個免費網站，幫助家人和朋友解決一些他們所遇到的電腦問題，還為教堂搭建了一個圖書館資料庫。</p><p>這意味着，我需要一直研究並嘗試獲取更多的信息，使它們變得更棒。互聯網上帝保佑我，讓開源進入我的視野。突然之間，30 天試用期和 license 限制對我而言就變成了過去式。我可以完全不受這些限制，繼續使用 GIMP、Inkscape 和 OpenOffice。</p><h3 id="是正經做些事情的時候了" tabindex="-1">是正經做些事情的時候了 <a class="header-anchor" href="#是正經做些事情的時候了" aria-label="Permalink to “是正經做些事情的時候了”">​</a></h3><p>我很幸運，有商業夥伴喜歡我的經歷。她也是個想像力豐富的人，期待更高效、更便捷的互聯世界。我們根據我們以往成功道路中經歷的弱點制定瞭解決方案，但執行卻成了一個問題。我們都缺乏給產品帶來活力的能力，每當我們試圖將想法帶到投資人面前時，這表現的尤為突出。</p><p>我們需要學習編程。於是 2015 年夏末，我們來到 Holberton 學校。那是一所座落於舊金山，由社區推進，基於項目教學的學校。</p><p>一天早晨我的商業夥伴來找我，以她獨有的方式（每當她有瘋狂想法想要拉我入夥時），進行一場對話。</p><p><strong>Zee</strong>: Gloria，我想和你説點事，在你説“不”前能先聽我説完嗎？</p><p><strong>Me</strong>: 不行。</p><p><strong>Zee</strong>: 為做全棧工程師，咱們申請上一所學校吧。</p><p><strong>Me</strong>: 什麼？</p><p><strong>Zee</strong>: 就是這，看！就是這所學校，我們要申請這所學校來學習編程。</p><p><strong>Me</strong>: 我不明白。我們不是正在網上學 Python 和…</p><p><strong>Zee</strong>: 這不一樣。相信我。</p><p><strong>Me</strong>: 那…</p><p><strong>Zee</strong>: 這就是不信任我了。</p><p><strong>Me</strong>: 好吧 … 給我看看。</p><h3 id="拋開偏見" tabindex="-1">拋開偏見 <a class="header-anchor" href="#拋開偏見" aria-label="Permalink to “拋開偏見”">​</a></h3><p>我讀到的和我們在網上看的的似乎很相似。這簡直太棒了，以至於讓人覺得不太真實，但我們還是決定嘗試一下，全力以赴，看看結果如何。</p><p>要成為學生，我們需要經歷四步選擇，不過選擇的依據僅僅是天賦和動機，而不是學歷和編程經歷。篩選便是課程的開始，通過它我們開始學習與合作。</p><p>根據我和我夥伴的經驗， Holberton 學校的申請流程比其他的申請流程有趣太多了，就像場遊戲。如果你完成了一項挑戰，就能通往下一關，在那裏有別的有趣的挑戰正等着你。我們創建了 Twitter 賬號，在 Medium 上寫Blog，為創建網站而學習 HTML 和 CSS， 打造了一個充滿活力的在線社區，雖然在此之前我們並不知曉有誰會來。</p><p>在線社區最吸引人的就是大家有多種多樣的使用電腦的經驗，而背景和性別不是社區創始人（我們私下裏稱他們為“The Trinity”）做出選擇的因素。大家只是喜歡聚在一塊兒交流。我們都行進在通過學習編程來提升自己計算機技術的旅途上。</p><p>相較於其他的的申請流程，我們不需要泄露很多的身份信息。就像我的夥伴，她的名字裏看不出她的性別和種族。直到最後一個步驟，在視頻聊天的時候， The Trinity 才知道她是一位有色人種女性。迄今為止，促使她達到這個級別的只是她的熱情和才華。膚色和性別並沒有妨礙或者幫助到她。還有比這更酷的嗎？</p>',31)),e("p",null,[t[1]||(t[1]=r("獲得錄取通知書的晚上，我們知道生活將向我們的夢想轉變。2016 年 1 月 22 日，我們來到巴特瑞大街 98 號，去見我們的同學們 ",-1)),n(o,{href:"https://twitter.com/hippokampoiers"},{default:p(()=>[...t[0]||(t[0]=[r("Hippokampoiers",-1)])]),_:1}),t[2]||(t[2]=r("，這是我們的初次見面。很明顯，在見面之前，“The Trinity”已經做了很多工作，聚集了一批形形色色的人，他們充滿激情與熱情，致力於成長為全棧工程師。",-1))]),e("p",null,[t[4]||(t[4]=r("這所學校有種與眾不同的體驗。每天都是向某一方面編程的一次竭力的衝鋒。交給我們的工程，並不會有很多指導，我們需要使用一切可以使用的資源找出解決方案。",-1)),n(o,{href:"https://www.holbertonschool.com/"},{default:p(()=>[...t[3]||(t[3]=[r("Holberton 學校",-1)])]),_:1}),t[5]||(t[5]=r(" 認為信息來源相較於以前已經大大豐富了。MOOC（大型開放式課程）、教程、可用的開源軟件和項目，以及線上社區等等，為我們完成項目提供了足夠的知識。加之寶貴的導師團隊來指導我們制定解決方案，這所學校變得並不僅僅是一所學校；我們已經成為了求學者的團體。任何對軟件工程感興趣並對這種學習方法感興趣的人，我都強烈推薦這所學校。在這裏的經歷會讓人有些悲喜交加，但是絕對值得。",-1))]),t[33]||(t[33]=e("h3",{id:"開源問題",tabindex:"-1"},[r("開源問題 "),e("a",{class:"header-anchor",href:"#開源問題","aria-label":"Permalink to “開源問題”"},"​")],-1)),e("p",null,[t[12]||(t[12]=r("我最早使用的開源系統是 ",-1)),n(o,{href:"https://en.wikipedia.org/wiki/Fedora_(operating_system)"},{default:p(()=>[...t[6]||(t[6]=[r("Fedora",-1)])]),_:1}),t[13]||(t[13]=r("，一個 ",-1)),n(o,{href:"https://www.redhat.com/"},{default:p(()=>[...t[7]||(t[7]=[r("Red Hat",-1)])]),_:1}),t[14]||(t[14]=r(" 贊助的項目。與 一名IRC 成員交流時，她推薦了這款免費的操作系統。 雖然在此之前，我還未獨自安裝過操作系統，但是這激起了我對開源的興趣和日常使用計算機時對開源軟件的依賴性。我們提倡為開源貢獻代碼，創造並使用開源的項目。我們的項目就在 Github 上，任何人都可以使用或是向它貢獻出自己的力量。我們也會使用或以自己的方式為一些既存的開源項目做出貢獻。在學校裏，我們使用的大部分工具是開源的，例如 Fedora、",-1)),n(o,{href:"https://www.vagrantup.com/"},{default:p(()=>[...t[8]||(t[8]=[r("Vagrant",-1)])]),_:1}),t[15]||(t[15]=r("、",-1)),n(o,{href:"https://www.virtualbox.org/"},{default:p(()=>[...t[9]||(t[9]=[r("VirtualBox",-1)])]),_:1}),t[16]||(t[16]=r("、",-1)),n(o,{href:"https://gcc.gnu.org/"},{default:p(()=>[...t[10]||(t[10]=[r("GCC",-1)])]),_:1}),t[17]||(t[17]=r(" 和 ",-1)),n(o,{href:"https://www.discourse.org/"},{default:p(()=>[...t[11]||(t[11]=[r("Discourse",-1)])]),_:1}),t[18]||(t[18]=r("，僅舉幾例。",-1))]),t[34]||(t[34]=e("p",null,"在向軟件工程師行進的路上，我始終憧憬着有朝一日能為開源社區做出一份貢獻，能與他人分享我所掌握的知識。",-1)),t[35]||(t[35]=e("h3",{id:"多樣性問題",tabindex:"-1"},[r("多樣性問題 "),e("a",{class:"header-anchor",href:"#多樣性問題","aria-label":"Permalink to “多樣性問題”"},"​")],-1)),t[36]||(t[36]=e("p",null,"站在教室裏，和 29 位求學者交流心得，真是令人陶醉。學員中 40% 是女性， 44% 是有色人種。當你是一位有色人種且為女性，並身處於這個以缺乏多樣性而著名的領域時，這些數字就變得非常重要了。這是高科技聖地麥加上的綠洲，我到達了。",-1)),t[37]||(t[37]=e("p",null,"想要成為一個全棧工程師是十分困難的，你甚至很難了解這意味着什麼。這是一條充滿挑戰但又有豐富回報的旅途。科技推動着未來飛速發展，而你也是美好未來很重要的一部分。雖然媒體在持續的關注解決科技公司的多樣化的問題，但是如果能認清自己，清楚自己的背景，知道自己為什麼想成為一名全棧工程師，你便能在某一方面迅速成長。",-1)),t[38]||(t[38]=e("p",null,"不過可能最重要的是，告訴大家，女性在計算機的發展史上扮演過多麼重要的角色，以幫助更多的女性迴歸到科技界，而且在給予就業機會時，不會因性別等因素而感到猶豫。女性的才能將會共同影響科技的未來，以及整個世界的未來。",-1)),t[39]||(t[39]=e("hr",null,null,-1)),e("p",null,[t[20]||(t[20]=r("via: ",-1)),n(o,{href:"https://opensource.com/life/16/4/my-open-source-story-gloria-bwandungi"},{default:p(()=>[...t[19]||(t[19]=[r("https://opensource.com/life/16/4/my-open-source-story-gloria-bwandungi",-1)])]),_:1})]),e("p",null,[t[24]||(t[24]=r("作者：",-1)),n(o,{href:"https://opensource.com/users/nappybrain"},{default:p(()=>[...t[21]||(t[21]=[r("Gloria Bwandungi",-1)])]),_:1}),t[25]||(t[25]=r(" 譯者：",-1)),n(o,{href:"https://github.com/martin2011qi"},{default:p(()=>[...t[22]||(t[22]=[r("martin2011qi",-1)])]),_:1}),t[26]||(t[26]=r(" 校對：",-1)),n(o,{href:"https://github.com/jasminepeng"},{default:p(()=>[...t[23]||(t[23]=[r("jasminepeng",-1)])]),_:1})]),e("p",null,[t[29]||(t[29]=r("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[27]||(t[27]=[r("LCTT",-1)])]),_:1}),t[30]||(t[30]=r(" 原創翻譯，",-1)),n(o,{href:"https://linux.cn/"},{default:p(()=>[...t[28]||(t[28]=[r("Linux中國",-1)])]),_:1}),t[31]||(t[31]=r(" 榮譽推出",-1))])])}const k=s(u,[["render",f]]);export{y as __pageData,k as default};
